let workspace=null,sharedRecord=null,accountProfile=null,projectBuilder=null,view='projects',onboardingStep=0,authState='loading';const proposalToken=location.hash.startsWith('#proposal=')?location.hash.slice(10):null;let projects=[],p,preview=false,readonly=!!proposalToken||location.hash.startsWith('#project=');const dialog=$('#dialog');
