 if(profile?.logo_url){const image=document.createElement('img');image.src=profile.logo_url;image.alt=profile.display_name||'Organisation home';wordmark.append(image);wordmark.setAttribute('aria-label',(profile.display_name||'Organisation')+' home');}
 else{wordmark.textContent=profile?.display_name?.trim()||'Seabird';wordmark.setAttribute('aria-label',(profile?.display_name?.trim()||'Seabird')+' home');}
 if(!readonly)render();
